57	/// Middleware that echoes `x-request-id` from request to response headers.
58	async fn echo_request_id_header(
59	    request: axum::extract::Request,
60	    next: axum::middleware::Next,
61	) -> axum::response::Response {
62	    let x_request_id = request.headers().get("x-request-id").cloned();
63	    let mut response = next.run(request).await;
64	    if let Some(value) = x_request_id {
65	        response.headers_mut().insert("x-request-id", value);
66	    }
67	    response
68	}
