78	/// Returns a protocol-compatible JSON `404` error response for an
79	/// unmatched route.
80	///
81	/// Requests under the configured Anthropic Messages path receive an Anthropic
82	/// error envelope. All other requests receive an OpenAI-compatible envelope.
83	async fn unmatched_route_fallback(
84	    axum::extract::State(state): axum::extract::State<UnmatchedRouteState>,
85	    method: axum::http::Method,
86	    uri: axum::http::Uri,
87	) -> axum::response::Response {
88	    match state.anthropic_path.as_deref() {
89	        Some(path) if path_within_namespace(uri.path(), path) => {
90	            super::anthropic::unmatched_route_response(&method, &uri)
91	        }
92	        _ => super::openai::unmatched_route_response(&method, &uri).into_response(),
93	    }
94	}
