96	/// Returns whether `path` is `namespace` or a route beneath it.
97	fn path_within_namespace(path: &str, namespace: &str) -> bool {
98	    let namespace = namespace.trim_end_matches('/');
99	    path.strip_prefix(namespace)
100	        .is_some_and(|rest| rest.is_empty() || rest.starts_with('/'))
101	}
102	
103	async fn track_inflight_inference(
104	    axum::extract::State(state): axum::extract::State<Arc<State>>,
105	    request: axum::extract::Request,
106	    next: axum::middleware::Next,
107	) -> axum::response::Response {
108	    use futures::StreamExt;
109	
110	    // Requests rejected during draining should not extend the drain window.
111	    if !state.is_ready() {
112	        return super::openai::ErrorMessage::_service_unavailable().into_response();
113	    }
114	
115	    let permit = state.acquire_inflight();
116	    // Close the race where shutdown starts after the readiness check but
117	    // before this request is counted as inflight.
118	    if !state.is_ready() {
119	        drop(permit);
120	        return super::openai::ErrorMessage::_service_unavailable().into_response();
121	    }
122	
123	    let response = next.run(request).await;
124	    let (parts, body) = response.into_parts();
125	    // Keep the permit alive until the full response body, including streams,
126	    // finishes or is dropped.
127	    let stream = body.into_data_stream().map(move |result| {
128	        let _permit = &permit;
129	        result
130	    });
131	    Response::from_parts(parts, Body::from_stream(stream))
132	}
