159	fn parse_sse_keep_alive(value: Result<String, std::env::VarError>) -> Option<Duration> {
160	    let value = match value {
161	        Ok(value) => value,
162	        Err(std::env::VarError::NotPresent) => return None,
163	        Err(error @ std::env::VarError::NotUnicode(_)) => {
164	            tracing::warn!(
165	                env = env_llm::DYN_HTTP_SSE_KEEP_ALIVE_INTERVAL_MS,
166	                %error,
167	                "ignoring invalid SSE keep-alive interval"
168	            );
169	            return None;
170	        }
171	    };
172	
173	    match value.parse::<u64>() {
174	        Ok(0) => None,
175	        Ok(milliseconds) => {
176	            let interval = Duration::from_millis(milliseconds);
177	            if std::time::Instant::now().checked_add(interval).is_some() {
178	                Some(interval)
179	            } else {
180	                tracing::warn!(
181	                    env = env_llm::DYN_HTTP_SSE_KEEP_ALIVE_INTERVAL_MS,
182	                    value,
183	                    "ignoring SSE keep-alive interval outside the platform range"
184	                );
185	                None
186	            }
187	        }
188	        Err(error) => {
189	            tracing::warn!(
