213	/// Lifecycle stage for the HTTP frontend.
214	///
215	/// The stage gates readiness and request admission separately from the runtime
216	/// cancellation token so the frontend can stop accepting new requests before
217	/// tearing down discovery and transport state.
218	#[derive(Clone, Copy, Debug, Eq, PartialEq)]
219	pub enum ServiceStage {
220	    /// The frontend is ready to admit new inference requests.
221	    Ready = 0,
222	    /// The frontend is rejecting new requests while admitted responses drain.
223	    Draining = 1,
224	    /// The frontend is cancelling runtime state and shutting down.
225	    Stopping = 2,
226	}
227	
228	impl ServiceStage {
229	    fn as_u8(self) -> u8 {
230	        self as u8
231	    }
232	
233	    fn from_u8(value: u8) -> Self {
234	        match value {
235	            0 => Self::Ready,
236	            1 => Self::Draining,
237	            _ => Self::Stopping,
238	        }
239	    }
240	}
241	
242	impl std::fmt::Display for ServiceStage {
243	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
244	        match self {
245	            Self::Ready => f.write_str("ready"),
246	            Self::Draining => f.write_str("draining"),
247	            Self::Stopping => f.write_str("stopping"),
248	        }
249	    }
250	}
