252	/// Shared HTTP frontend lifecycle and inflight request tracker.
253	///
254	/// `ServiceObserver` is shared by HTTP handlers, health endpoints, and the
255	/// shutdown path. It lets shutdown first mark the frontend as draining, then
256	/// wait for admitted inference response bodies to complete before cancelling
257	/// runtime state.
258	#[derive(Debug)]
259	pub struct ServiceObserver {
260	    stage: AtomicU8,
261	    inflight_inference: AtomicU64,
262	    inflight_zero: Notify,
263	}
264	
265	impl Default for ServiceObserver {
266	    fn default() -> Self {
267	        Self {
268	            stage: AtomicU8::new(ServiceStage::Ready.as_u8()),
269	            inflight_inference: AtomicU64::new(0),
270	            inflight_zero: Notify::new(),
271	        }
272	    }
273	}
274	
275	impl ServiceObserver {
276	    /// Return the current frontend lifecycle stage.
277	    pub fn stage(&self) -> ServiceStage {
278	        ServiceStage::from_u8(self.stage.load(Ordering::Acquire))
279	    }
280	
281	    /// Return true when the frontend should admit new inference requests.
282	    pub fn is_ready(&self) -> bool {
283	        self.stage() == ServiceStage::Ready
284	    }
285	
286	    /// Mark the frontend as draining.
287	    ///
288	    /// Draining makes readiness fail and causes request admission checks to
289	    /// reject new inference requests while existing response bodies continue.
290	    pub fn start_draining(&self) {
291	        tracing::info!(
292	            previous_stage = ?self.stage(),
293	            inflight_requests = self.inflight_count(),
294	            "frontend service entering draining stage"
295	        );
296	        self.stage
297	            .store(ServiceStage::Draining.as_u8(), Ordering::Release);
298	    }
299	
300	    /// Mark the frontend as stopping.
301	    ///
302	    /// Stopping is entered after inflight requests drain or the graceful
303	    /// shutdown timeout expires.
304	    pub fn start_stopping(&self) {
305	        tracing::info!(
306	            previous_stage = ?self.stage(),
307	            inflight_requests = self.inflight_count(),
308	            "frontend service entering stopping stage"
309	        );
310	        self.stage
311	            .store(ServiceStage::Stopping.as_u8(), Ordering::Release);
312	    }
313	
314	    /// Track one admitted inference response body.
315	    ///
316	    /// The returned permit must live for the full HTTP response body lifetime,
317	    /// including streaming responses. Dropping the permit decrements the
318	    /// inflight count and wakes shutdown waiters when the count reaches zero.
319	    pub fn acquire_inflight(self: &Arc<Self>) -> InflightPermit {
320	        self.inflight_inference.fetch_add(1, Ordering::Relaxed);
321	        InflightPermit {
322	            observer: self.clone(),
323	        }
324	    }
325	
326	    /// Return the number of admitted inference requests still in flight.
327	    pub fn inflight_count(&self) -> u64 {
328	        self.inflight_inference.load(Ordering::Acquire)
329	    }
330	
331	    /// Wait until all admitted inference requests drain or `timeout` expires.
332	    ///
333	    /// Returns `true` when inflight work drained before the timeout and `false`
334	    /// when shutdown should proceed because the timeout expired.
335	    pub async fn wait_inflight_zero_or_timeout(&self, timeout: Duration) -> bool {
336	        tokio::time::timeout(timeout, async {
337	            loop {
338	                let notified = self.inflight_zero.notified();
339	                tokio::pin!(notified);
340	                // Register before reading the count so a final permit drop
341	                // cannot notify between the count check and the await.
342	                notified.as_mut().enable();
343	                if self.inflight_count() == 0 {
344	                    break;
345	                }
346	                notified.as_mut().await;
347	            }
348	        })
349	        .await
350	        .is_ok()
351	    }
352	}
353	
354	/// RAII guard for one admitted inference response.
355	///
356	/// This permit is held by a response-body wrapper so it is released only when
357	/// the client response body finishes or is dropped.
358	pub struct InflightPermit {
359	    observer: Arc<ServiceObserver>,
360	}
361	
362	impl Drop for InflightPermit {
363	    fn drop(&mut self) {
364	        if self
365	            .observer
366	            .inflight_inference
367	            .fetch_sub(1, Ordering::AcqRel)
368	            == 1
369	            && self.observer.stage() != ServiceStage::Ready
370	        {
371	            self.observer.inflight_zero.notify_waiters();
372	        }
373	    }
374	}
