802	    /// binding `{host}:{port}` internally. See [`spawn_with_listener`] for the TLS
803	    /// restriction.
804	    ///
805	    /// [`run`]: HttpService::run
806	    /// [`spawn_with_listener`]: HttpService::spawn_with_listener
807	    pub async fn run_with_listener(
808	        &self,
809	        cancel_token: CancellationToken,
810	        listener: tokio::net::TcpListener,
811	    ) -> Result<()> {
812	        self.run_inner(cancel_token, Some(listener)).await
813	    }
814	
815	    async fn run_inner(
816	        &self,
817	        cancel_token: CancellationToken,
818	        listener: Option<tokio::net::TcpListener>,
819	    ) -> Result<()> {
820	        let address = format!("{}:{}", self.host, self.port);
821	        let protocol = if self.enable_tls { "HTTPS" } else { "HTTP" };
822	        tracing::info!(protocol, address, "Starting HTTP(S) service");
823	
824	        let router = self.router.clone();
825	        let observer = cancel_token.child_token();
826	
827	        let state = self.state.clone();
828	        let state_cancel = state.cancel_token().clone();
829	
830	        if self.enable_tls {
831	            if listener.is_some() {
832	                return Err(anyhow::anyhow!(
833	                    "Pre-bound listener is not supported in TLS mode; \
834	                     axum_server::bind_rustls owns its own bind. \
835	                     Use run()/spawn() (which bind internally) when enable_tls is set."
836	                ));
837	            }
838	            let addr: SocketAddr = address
839	                .parse()
840	                .map_err(|e| anyhow::anyhow!("Invalid address '{}': {}", address, e))?;
841	            let cert_path = self
842	                .tls_cert_path
843	                .as_ref()
844	                .ok_or_else(|| anyhow::anyhow!("TLS certificate path not provided"))?;
845	            let key_path = self
846	                .tls_key_path
847	                .as_ref()
848	                .ok_or_else(|| anyhow::anyhow!("TLS private key path not provided"))?;
849	
850	            // aws_lc_rs is the default but other crates pull in `ring` also,
851	            // so rustls doesn't know which one to use. Tell it.
852	            if let Err(e) = rustls::crypto::aws_lc_rs::default_provider().install_default() {
853	                tracing::debug!("TLS crypto provider already installed: {e:?}");
854	            }
855	
856	            let config = RustlsConfig::from_pem_file(cert_path, key_path)
857	                .await
858	                .map_err(|e| anyhow::anyhow!("Failed to create TLS config: {}", e))?;
859	
860	            let handle = axum_server::Handle::new();
861	            let server = axum_server::bind_rustls(addr, config)
862	                .handle(handle.clone())
863	                .serve(router.into_make_service());
864	
865	            self.spawn_rl_listener_if_configured(&cancel_token).await?;
866	
867	            // Spawn canary after all fallible startup so it won't leak on early errors
868	            tokio::spawn(tokio_metrics_and_canary_loop(cancel_token.clone()));
869	
870	            tokio::select! {
871	                result = server => {
872	                    let result = result.map_err(|e| anyhow::anyhow!("HTTPS server error: {}", e));
873	                    state.start_stopping();
874	                    cancel_token.cancel();
875	                    result?;
876	                }
877	                _ = observer.cancelled() => {
878	                    state.start_draining();
879	                    tracing::info!("HTTPS server shutdown requested");
880	                    let shutdown_timeout =
881	                        Duration::from_secs(get_graceful_shutdown_timeout() as u64);
882	                    handle.graceful_shutdown(Some(shutdown_timeout));
883	                    if !state.wait_inflight_zero_or_timeout(shutdown_timeout).await {
884	                        tracing::warn!(
885	                            inflight_requests = state.inflight_count(),
886	                            "Timed out waiting for inflight inference requests to drain"
887	                        );
888	                    }
889	                    state.start_stopping();
890	                    state_cancel.cancel();
891	                }
892	            }
893	        } else {
894	            let listener = match listener {
895	                Some(l) => l,
896	                None => {
897	                    let addr: SocketAddr = address
898	                        .parse()
899	                        .map_err(|e| anyhow::anyhow!("Invalid address '{}': {}", address, e))?;
900	                    tokio::net::TcpListener::bind(addr).await.map_err(|e| {
901	                        tracing::error!(
902	                            protocol = %protocol,
903	                            address = %address,
904	                            error = %e,
905	                            "Failed to bind server to address"
906	                        );
907	                        match e.kind() {
908	                            std::io::ErrorKind::AddrInUse => anyhow::anyhow!(
909	                                "Failed to start {} server: port {} already in use. Use --http-port to specify a different port.",
910	                                protocol,
911	                                self.port
912	                            ),
913	                            _ => anyhow::anyhow!(
914	                                "Failed to start {} server on {}: {}",
915	                                protocol,
916	                                address,
917	                                e
918	                            ),
919	                        }
920	                    })?
921	                }
922	            };
923	
924	            self.spawn_rl_listener_if_configured(&cancel_token).await?;
925	
926	            // Spawn canary after all fallible startup so it won't leak on early errors
927	            tokio::spawn(tokio_metrics_and_canary_loop(cancel_token.clone()));
928	
929	            let state = self.state.clone();
930	            axum::serve(listener, router)
931	                .with_graceful_shutdown(async move {
932	                    observer.cancelled_owned().await;
933	                    state.start_draining();
934	                    tracing::info!("HTTP server shutdown requested");
935	                    let shutdown_timeout =
936	                        Duration::from_secs(get_graceful_shutdown_timeout() as u64);
937	                    if !state.wait_inflight_zero_or_timeout(shutdown_timeout).await {
938	                        tracing::warn!(
939	                            inflight_requests = state.inflight_count(),
940	                            "Timed out waiting for inflight inference requests to drain"
941	                        );
942	                    }
943	                    state.start_stopping();
944	                    state_cancel.cancel();
945	                })
946	                .await
947	                .inspect_err(|_| {
948	                    self.state.start_stopping();
949	                    cancel_token.cancel()
950	                })?;
951	            self.state.start_stopping();
952	            cancel_token.cancel();
953	        }
954	
955	        Ok(())
956	    }
957	
958	    async fn spawn_rl_listener_if_configured(
959	        &self,
960	        cancel_token: &CancellationToken,
961	    ) -> Result<()> {
962	        let Some(rl_router) = self.rl_router.clone() else {
963	            return Ok(());
964	        };
965	        let rl_addr = format!("{}:{}", self.host, self.rl_port);
966	        // Bind eagerly and fail fast: when RL discovery is enabled, a bind failure
967	        // should abort service startup rather than silently leave RL discovery
968	        // unavailable while the main HTTP service keeps running.
969	        let listener = tokio::net::TcpListener::bind(&rl_addr).await.map_err(|e| {
970	            tracing::error!(
971	                address = %rl_addr,
972	                error = %e,
973	                "Failed to bind RL worker discovery listener"
974	            );
975	            anyhow::anyhow!("Failed to bind RL worker discovery listener on {rl_addr}: {e}")
976	        })?;
977	        tracing::info!(
978	            address = %rl_addr,
979	            "RL worker discovery listener started"
980	        );
981	        let rl_cancel = cancel_token.child_token();
982	        tokio::spawn(async move {
983	            if let Err(e) = axum::serve(listener, rl_router)
984	                .with_graceful_shutdown(async move {
985	                    rl_cancel.cancelled_owned().await;
986	                })
987	                .await
988	            {
989	                tracing::error!("RL worker discovery listener error: {e}");
990	            }
991	        });
992	        Ok(())
993	    }
