1065	fn validate_generate_route_path(path: &str) -> Result<()> {
1066	    if !path.starts_with("/") {
1067	        anyhow::bail!("Generate route path must start with '/': {path:?}");
1068	    }
1069	    if path
1070	        .split('/')
1071	        .any(|segment| segment.starts_with([':', '*']))
1072	    {
1073	        anyhow::bail!("Generate route path segment must not start with ':' or '*': {path:?}");
1074	    }
1075	    Ok(())
1076	}
