1078	fn append_route_docs(
1079	    all_docs: &mut Vec<RouteDoc>,
1080	    seen_routes: &mut HashSet<RouteDoc>,
1081	    route_docs: Vec<RouteDoc>,
1082	) -> Result<()> {
1083	    for route_doc in route_docs {
1084	        if let Some(existing) = seen_routes.get(&route_doc) {
1085	            anyhow::bail!("duplicate HTTP route registered: {route_doc} conflicts with {existing}");
1086	        }
1087	        seen_routes.insert(route_doc.clone());
1088	        all_docs.push(route_doc);
1089	    }
1090	    Ok(())
1091	}
