1113	        let metrics_config = config.metrics_config.clone();
1114	        let frontend_api_config = config.frontend_api_config.clone();
1115	        let anthropic_endpoints_enabled = frontend_api_config.anthropic().enabled();
1116	        let vllm_generate_enabled =
1117	            config.enable_engine_apis || env_is_truthy(VLLM_ENABLE_INFERENCE_V1_GENERATE_ENV);
1118	        let sglang_generate_enabled =
1119	            config.enable_engine_apis || env_is_truthy(SGLANG_ENABLE_GENERATE_ENV);
1120	        let generate_engine_capabilities = [
1121	            vllm_generate_enabled.then_some(VLLM_INFERENCE_V1_GENERATE_CAPABILITY),
1122	            sglang_generate_enabled.then_some(SGLANG_GENERATE_CAPABILITY),
1123	        ]
1124	        .into_iter()
1125	        .flatten()
1126	        .collect::<Vec<_>>();
1127	
1128	        let model_manager = Arc::new(ModelManager::new());
1129	        let cancel_token = config.cancel_token.unwrap_or_default();
1130	        // Use the provided discovery client, or fall back to a no-op memory-backed one
1131	        // (for in-process modes that don't need discovery)
1132	        let discovery_client = config.discovery.unwrap_or_else(|| {
1133	            use dynamo_runtime::discovery::KVStoreDiscovery;
1134	            Arc::new(KVStoreDiscovery::new(
1135	                dynamo_runtime::storage::kv::Manager::memory(),
1136	                cancel_token.child_token(),
1137	            )) as Arc<dyn Discovery>
1138	        });
1139	        // Both surfaces are on by default; an env-truthy DISABLE var turns them
1140	        // off. The builder flag can also force off (e.g. tests), and wins.
1141	        let nvext_enabled =
1142	            config.enable_nvext && !env_is_truthy(env_llm::DYN_DISABLE_FRONTEND_NVEXT);
1143	        let admin_api_enabled =
1144	            config.enable_admin_api && !env_is_truthy(env_llm::DYN_DISABLE_FRONTEND_ADMIN_API);
1145	        let state = Arc::new(State::new(
1146	            model_manager,
1147	            discovery_client,
1148	            cancel_token,
