1306	
1307	        system_router = system_router.layer(
1308	            TraceLayer::new_for_http()
1309	                .make_span_with(make_system_request_span)
1310	                .on_response(on_response),
1311	        );
1312	
1313	        let router = system_router.merge(inference_router);
1314	
1315	        // Return protocol-compatible JSON errors for unmatched routes. Register this router
1316	        // outside `track_inflight_inference` so unmatched requests do not acquire an
1317	        // inference permit or return `503` while the service is draining.
1318	        let unmatched_router = axum::Router::new()
1319	            .fallback(unmatched_route_fallback)
1320	            .with_state(UnmatchedRouteState {
1321	                anthropic_path: anthropic_endpoints_enabled.then(|| {
1322	                    var(HTTP_SVC_ANTHROPIC_PATH_ENV)
1323	                        .unwrap_or_else(|_| super::anthropic::DEFAULT_MESSAGES_PATH.to_string())
1324	                        .into()
1325	                }),
1326	            })
1327	            .layer(
1328	                // Use the inference span maker so 404s retain method, URI, and request ID
1329	                // at the default log level.
1330	                TraceLayer::new_for_http()
1331	                    .make_span_with(make_inference_request_span)
1332	                    .on_response(on_response),
1333	            );
1334	        let router = router.fallback_service(unmatched_router);
1335	
1336	        // Echo x-request-id from request to response headers for client correlation
1337	        let router = router.layer(axum::middleware::from_fn(echo_request_id_header));
1338	
1339	        let enable_rl_router = config.enable_rl || env_is_truthy("DYN_ENABLE_RL");
1340	        let rl_router = if enable_rl_router {
1341	            let Some(drt) = config.runtime.as_ref() else {
1342	                return Err(anyhow::anyhow!(
1343	                    "RL worker discovery was requested (DYN_ENABLE_RL=true \
1344	                     or enable_rl) but HttpServiceConfig.runtime is not set."
1345	                ));
1346	            };
1347	            let router = super::openai::rl_router(drt.clone())?;
1348	            tracing::info!(
1349	                rl_port = config.rl_port,
1350	                "RL worker discovery enabled at /v1/rl/workers"
1351	            );
1352	            Some(
1353	                router.layer(
1354	                    TraceLayer::new_for_http()
1355	                        .make_span_with(make_system_request_span)
1356	                        .on_response(on_response),
1357	                ),
1358	            )
1359	        } else {
1360	            None
1361	        };
1362	
1363	        Ok(HttpService {
1364	            state,
1365	            router,
1366	            port: config.port,
1367	            host: config.host,
1368	            enable_tls: config.enable_tls,
1369	            tls_cert_path: config.tls_cert_path,
1370	            tls_key_path: config.tls_key_path,
1371	            route_docs: all_docs,
1372	            generate_engine_capabilities,
1373	            rl_router,
1374	            rl_port: config.rl_port,
1375	        })
1376	    }
