1427	    fn get_endpoints_router(
1428	        state: Arc<State>,
1429	        request_template: &Option<RequestTemplate>,
1430	        enable_anthropic_endpoints: bool,
1431	        vllm_generate_enabled: bool,
1432	        sglang_generate_enabled: bool,
1433	        enable_batch_endpoints: bool,
1434	    ) -> Result<Vec<(Vec<RouteDoc>, axum::Router)>> {
1435	        let mut routes = Vec::new();
1436	        // Add chat completions route with conditional middleware
1437	        let (chat_docs, chat_route) = super::openai::chat_completions_router(
1438	            state.clone(),
1439	            request_template.clone(),
1440	            var(HTTP_SVC_CHAT_PATH_ENV).ok(),
1441	        );
1442	        let (cmpl_docs, cmpl_route) =
1443	            super::openai::completions_router(state.clone(), var(HTTP_SVC_CMP_PATH_ENV).ok());
1444	        let (embed_docs, embed_route) =
1445	            super::openai::embeddings_router(state.clone(), var(HTTP_SVC_EMB_PATH_ENV).ok());
1446	        let (classify_docs, classify_route) =
1447	            super::openai::classify_router(state.clone(), var(HTTP_SVC_CLASSIFY_PATH_ENV).ok());
1448	        let (pooling_docs, pooling_route) =
1449	            super::openai::pooling_router(state.clone(), var(HTTP_SVC_POOLING_PATH_ENV).ok());
1450	        let (images_docs, images_route) = super::openai::images_router(state.clone(), None);
1451	        let (videos_docs, videos_route) = super::openai::videos_router(state.clone(), None);
1452	        let (audios_docs, audios_route) = super::openai::audios_router(state.clone(), None);
1453	        let (realtime_docs, realtime_route) = super::realtime::realtime_router(state.clone(), None);
1454	        let (responses_docs, responses_route) = super::openai::responses_router(
1455	            state.clone(),
1456	            request_template.clone(),
1457	            var(HTTP_SVC_RESPONSES_PATH_ENV).ok(),
1458	        );
1459	        let mut endpoint_routes = HashMap::new();
1460	        endpoint_routes.insert(EndpointType::Chat, (chat_docs, chat_route));
1461	        endpoint_routes.insert(EndpointType::Completion, (cmpl_docs, cmpl_route));
1462	        endpoint_routes.insert(EndpointType::Embedding, (embed_docs, embed_route));
1463	        endpoint_routes.insert(EndpointType::Classify, (classify_docs, classify_route));
1464	        endpoint_routes.insert(EndpointType::Pooling, (pooling_docs, pooling_route));
1465	        endpoint_routes.insert(EndpointType::Images, (images_docs, images_route));
1466	        endpoint_routes.insert(EndpointType::Videos, (videos_docs, videos_route));
1467	        endpoint_routes.insert(EndpointType::Audios, (audios_docs, audios_route));
1468	        endpoint_routes.insert(EndpointType::Realtime, (realtime_docs, realtime_route));
1469	        endpoint_routes.insert(EndpointType::Responses, (responses_docs, responses_route));
1470	
1471	        if enable_batch_endpoints {
1472	            let (batch_docs, batch_route) = super::openai::batch_router(
1473	                state.clone(),
1474	                var(HTTP_SVC_FILES_PATH_ENV).ok(),
1475	                var(HTTP_SVC_BATCHES_PATH_ENV).ok(),
1476	            );
1477	            endpoint_routes.insert(EndpointType::Batch, (batch_docs, batch_route));
1478	        }
1479	
1480	        if enable_anthropic_endpoints {
1481	            tracing::warn!("Anthropic Messages API (/v1/messages) is experimental.");
1482	            let (anthropic_docs, anthropic_route) = super::anthropic::anthropic_messages_router(
1483	                state.clone(),
1484	                request_template.clone(),
1485	                var(HTTP_SVC_ANTHROPIC_PATH_ENV).ok(),
1486	            );
1487	            endpoint_routes.insert(
1488	                EndpointType::AnthropicMessages,
1489	                (anthropic_docs, anthropic_route),
1490	            );
1491	        }
1492	
1493	        if vllm_generate_enabled || sglang_generate_enabled {
1494	            tracing::warn!("The engine-native Generate APIs are experimental.");
1495	            let mut generate_docs = Vec::new();
1496	            let mut generate_route = axum::Router::new();
1497	            if vllm_generate_enabled {
1498	                let generate_path = var(HTTP_SVC_VLLM_GENERATE_PATH_ENV).ok();
1499	                if let Some(path) = generate_path.as_deref() {
1500	                    validate_generate_route_path(path)?;
1501	                }
1502	                let (docs, route) = super::generate::generate_router(state.clone(), generate_path);
1503	                generate_docs.extend(docs);
1504	                generate_route = generate_route.merge(route);
1505	            }
1506	            if sglang_generate_enabled {
1507	                let generate_path = var(HTTP_SVC_SGLANG_GENERATE_PATH_ENV).ok();
1508	                if let Some(path) = generate_path.as_deref() {
1509	                    validate_generate_route_path(path)?;
1510	                }
1511	                let (docs, route) = super::sglang_generate::router(state.clone(), generate_path);
1512	                generate_docs.extend(docs);
1513	                generate_route = generate_route.merge(route);
1514	            }
1515	            endpoint_routes.insert(EndpointType::Generate, (generate_docs, generate_route));
1516	        }
1517	
1518	        for endpoint_type in EndpointType::all() {
1519	            let state_route = state.clone();
1520	            if !endpoint_routes.contains_key(&endpoint_type) {
1521	                tracing::debug!("{} endpoints are disabled", endpoint_type.as_str());
1522	                continue;
1523	            }
1524	            let (docs, route) = endpoint_routes.get(&endpoint_type).cloned().unwrap();
1525	            let route = route.route_layer(axum::middleware::from_fn(
1526	                move |req: axum::http::Request<axum::body::Body>, next: axum::middleware::Next| {
1527	                    let state: Arc<State> = state_route.clone();
1528	                    async move {
1529	                        // Check if the endpoint is enabled
1530	                        let enabled = state.flags.get(&endpoint_type);
1531	                        if enabled {
1532	                            Ok(next.run(req).await)
1533	                        } else {
1534	                            tracing::debug!("{} endpoints are disabled", endpoint_type.as_str());
1535	                            Err(axum::http::StatusCode::NOT_FOUND)
1536	                        }
1537	                    }
1538	                },
1539	            ));
1540	            routes.push((docs, route));
1541	        }
1542	        Ok(routes)
1543	    }
1544	}
