1755	    /// Starts an `HttpService` on an ephemeral local port.
1756	    ///
1757	    /// Applies `configure` before starting the service. These tests run before the
1758	    /// readiness check, so no model registration is required.
1759	    async fn spawn_service(
1760	        configure: impl FnOnce(HttpServiceConfigBuilder) -> HttpServiceConfigBuilder,
1761	    ) -> (u16, Arc<State>, tokio::task::JoinHandle<()>) {
1762	        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
1763	        let port = listener.local_addr().unwrap().port();
1764	        let service = configure(HttpService::builder().port(port))
1765	            .build()
1766	            .unwrap();
1767	        let state = service.state_clone();
1768	        let handle = tokio::spawn(async move {
1769	            service
1770	                .run_with_listener(CancellationToken::new(), listener)
1771	                .await
1772	                .ok();
1773	        });
1774	
1775	        // Allow the server to begin accepting connections.
1776	        tokio::time::sleep(Duration::from_millis(20)).await;
1777	
1778	        (port, state, handle)
1779	    }
