2281	    /// `DYN_DISABLE_FRONTEND_NVEXT` is the env-var mirror of the builder
2282	    /// flag. Unset -> builder default wins (on). Falsey strings -> on.
2283	    /// Truthy strings (`1` / `true` / `yes` / `on`, case-insensitive) ->
2284	    /// off, regardless of what the builder asked for.
2285	    #[test]
2286	    #[serial_test::serial]
2287	    fn test_dyn_disable_frontend_nvext_env_var_mirror() {
2288	        use dynamo_runtime::config::environment_names::llm::DYN_DISABLE_FRONTEND_NVEXT;
2289	
2290	        // Unset -> builder default (true) wins.
2291	        temp_env::with_var_unset(DYN_DISABLE_FRONTEND_NVEXT, || {
2292	            let svc = HttpService::builder().build().unwrap();
2293	            assert!(
2294	                svc.state.nvext_enabled(),
2295	                "unset env + default builder = on"
2296	            );
2297	        });
2298	
2299	        // Explicit falsey -> still on (disable not requested).
2300	        temp_env::with_var(DYN_DISABLE_FRONTEND_NVEXT, Some("false"), || {
2301	            let svc = HttpService::builder().build().unwrap();
2302	            assert!(
2303	                svc.state.nvext_enabled(),
2304	                "disable=false + default builder = on"
2305	            );
2306	        });
2307	
2308	        // Explicit truthy -> off, even though the builder default is on.
2309	        for truthy in ["true", "1", "yes", "on", "TRUE"] {
2310	            temp_env::with_var(DYN_DISABLE_FRONTEND_NVEXT, Some(truthy), || {
2311	                let svc = HttpService::builder().build().unwrap();
2312	                assert!(
2313	                    !svc.state.nvext_enabled(),
2314	                    "disable={truthy:?} should override builder default to off"
2315	                );
2316	            });
2317	        }
2318	
2319	        // Builder=false short-circuits regardless of env.
2320	        temp_env::with_var_unset(DYN_DISABLE_FRONTEND_NVEXT, || {
2321	            let svc = HttpService::builder().enable_nvext(false).build().unwrap();
2322	            assert!(
2323	                !svc.state.nvext_enabled(),
2324	                "builder=false wins even if disable is unset"
2325	            );
2326	        });
2327	    }
