4	//! HTTP handler for the token-in/token-out `Generate` API
5	//! (`POST /inference/v1/generate`).
6	//!
7	//! This is an experimental engine-native endpoint, **disabled by default**;
8	//! opt in via the `enable_engine_apis` builder flag or the
9	//! `DYN_VLLM_ENABLE_INFERENCE_V1_GENERATE` env var. When enabled it registers
10	//! a frontend-native handler that preserves the complete request in an opaque
11	//! backend envelope. Streaming (`stream=true`) remains unimplemented.
12	
13	use std::sync::Arc;
14	
15	use axum::{
16	    Json, Router,
17	    extract::State,
18	    http::{HeaderMap, StatusCode},
19	    middleware,
20	    response::{IntoResponse, Response},
21	    routing::post,
22	};
23	use dynamo_runtime::pipeline::{AsyncEngineContext, AsyncEngineContextProvider, Context};
24	use serde::Serialize;
25	use tracing::Instrument;
26	
27	use super::disconnect::create_connection_monitor;
28	use super::metrics::{CancellationLabels, ErrorType};
29	use super::openai::{
30	    check_model_serving_ready, check_ready, context_from_headers, get_body_limit,
31	    get_or_create_request_id, smart_json_error_middleware,
32	};
33	use super::{RouteDoc, service_v2};
34	use crate::local_model::runtime_config::VLLM_INFERENCE_V1_GENERATE_CAPABILITY;
35	use crate::protocols::common::preprocessor::{MmRoutingInfo, PreprocessedRequest};
36	use crate::protocols::common::{SamplingOptions, StopConditions};
37	use crate::protocols::openai::generate::{
38	    GenerateRequest, GenerateResponse, GenerateResponseOptions, SamplingParams, StreamOptions,
39	};
40	
41	const X_REQUEST_ID_HEADER: &str = "x-request-id";
42	const X_DATA_PARALLEL_RANK_HEADER: &str = "x-data-parallel-rank";
43	
44	#[derive(Debug)]
45	struct GenerateRequestContext {
46	    request_id: String,
47	    data_parallel_rank: Option<u32>,
48	}
49	
50	/// vLLM-style nested error body: `{"error": {"message", "type", "code"}}`.
51	#[derive(Serialize, Debug)]
52	struct GenerateError {
53	    error: GenerateErrorBody,
54	}
55	
56	#[derive(Serialize, Debug)]
57	struct GenerateErrorBody {
58	    message: String,
59	    #[serde(rename = "type")]
60	    error_type: String,
61	    code: u16,
62	}
63	
64	/// Create an Axum [`Router`] for the token-in/token-out `Generate` endpoint.
65	/// If no path is provided, the default path is `/inference/v1/generate`.
66	pub fn generate_router(
67	    state: Arc<service_v2::State>,
68	    path: Option<String>,
69	) -> (Vec<RouteDoc>, Router) {
70	    let path = path.unwrap_or("/inference/v1/generate".to_string());
71	    let doc = RouteDoc::new(axum::http::Method::POST, &path);
72	    let router = Router::new()
73	        .route(&path, post(handler_generate))
74	        .layer(middleware::from_fn(smart_json_error_middleware))
75	        .layer(axum::extract::DefaultBodyLimit::max(get_body_limit()))
76	        .with_state(state);
77	    (vec![doc], router)
78	}
79	
80	/// Build a vLLM-style nested-`error` response.
81	fn generate_error_response(code: StatusCode, error_type: &str, message: String) -> Response {
82	    (
83	        code,
84	        Json(GenerateError {
85	            error: GenerateErrorBody {
86	                message,
87	                error_type: error_type.to_string(),
88	                code: code.as_u16(),
89	            },
90	        }),
91	    )
92	        .into_response()
93	}
94	
95	/// Resolve the request metadata that vLLM keeps outside the public JSON body.
96	fn resolve_generate_request_context(
97	    headers: &HeaderMap,
98	    body_request_id: Option<&str>,
99	) -> GenerateRequestContext {
100	    let request_id = headers
101	        .get(X_REQUEST_ID_HEADER)
102	        .and_then(|value| value.to_str().ok())
103	        .map(ToOwned::to_owned)
104	        .or_else(|| body_request_id.map(ToOwned::to_owned))
105	        .unwrap_or_else(|| get_or_create_request_id(headers));
106	    let data_parallel_rank = headers
107	        .get(X_DATA_PARALLEL_RANK_HEADER)
108	        .and_then(|value| value.to_str().ok())
109	        .and_then(|value| value.trim().parse().ok());
110	
111	    GenerateRequestContext {
112	        request_id,
113	        data_parallel_rank,
114	    }
115	}
116	
117	/// Convert vLLM's lower-is-higher priority to Dynamo's higher-is-higher scale.
118	fn dynamo_routing_priority(vllm_priority: i32) -> i32 {
119	    vllm_priority.saturating_neg()
120	}
121	
122	fn generate_dispatch_span(request_id: &str) -> tracing::Span {
123	    tracing::info_span!(target: "request_span", "generate", request_id = %request_id)
124	}
125	
126	async fn run_until_killed<T>(
127	    context: &dyn AsyncEngineContext,
128	    operation: impl std::future::Future<Output = T>,
129	) -> Option<T> {
130	    tokio::pin!(operation);
131	    tokio::select! {
132	        biased;
133	
134	        // Preserve an ownership-bearing result if it completes concurrently;
135	        // callers re-check the context before using it.
136	        result = &mut operation => Some(result),
137	        _ = context.killed() => None,
138	    }
139	}
140	
141	fn generate_cancelled_response() -> Response {
142	    generate_error_response(
143	        StatusCode::from_u16(499).unwrap_or(StatusCode::BAD_REQUEST),
144	        "request_cancelled",
145	        "request was cancelled".to_string(),
146	    )
147	}
148	
149	fn generate_internal_error_response() -> Response {
150	    generate_error_response(
151	        StatusCode::INTERNAL_SERVER_ERROR,
152	        "internal_error",
