583	async fn handler_generate(
584	    State(state): State<Arc<service_v2::State>>,
585	    headers: HeaderMap,
586	    Json(request): Json<GenerateRequest>,
587	) -> Response {
588	    if let Err(response) = check_ready(&state) {
589	        return response.into_response();
590	    }
591	
592	    if let Err(message) = request.validate() {
593	        return generate_error_response(StatusCode::BAD_REQUEST, "invalid_request_error", message);
594	    }
595	
596	    if request.stream {
597	        return generate_error_response(
598	            StatusCode::NOT_IMPLEMENTED,
599	            "not_implemented",
600	            "streaming (stream=true) is not implemented for /inference/v1/generate yet".to_string(),
601	        );
602	    }
603	    let response_options = request.response_options();
604	
605	    let model = match &request.model {
606	        Some(model) => model.clone(),
607	        None => {
608	            let models = state
609	                .manager()
610	                .list_generate_models_for_capability(VLLM_INFERENCE_V1_GENERATE_CAPABILITY);
611	            match models.len() {
612	                1 => models.into_iter().next().unwrap(),
613	                0 => {
614	                    return generate_error_response(
615	                        StatusCode::NOT_FOUND,
616	                        "not_found",
617	                        "no generate-capable model is registered".to_string(),
618	                    );
619	                }
620	                _ => {
621	                    return generate_error_response(
622	                        StatusCode::BAD_REQUEST,
623	                        "invalid_request_error",
624	                        "multiple models are registered; specify `model` in the request"
625	                            .to_string(),
626	                    );
627	                }
628	            }
629	        }
630	    };
631	
632	    if let Err(response) = check_model_serving_ready(&state, &model) {
633	        return response.into_response();
634	    }
635	
636	    let selection = match state
637	        .manager()
638	        .get_generate_engine_for_capability_with_routing(
639	            &model,
640	            VLLM_INFERENCE_V1_GENERATE_CAPABILITY,
641	        ) {
642	        Ok(selection) => selection,
643	        Err(error) => {
644	            let (status, error_type) = match error {
645	                crate::discovery::ModelManagerError::ModelUnavailable(_) => {
646	                    (StatusCode::SERVICE_UNAVAILABLE, "service_unavailable")
647	                }
648	                _ => (StatusCode::NOT_FOUND, "not_found"),
649	            };
650	            return generate_error_response(status, error_type, error.to_string());
651	        }
652	    };
653	    let routing_metadata = GenerateRoutingMetadata {
654	        kv_cache_block_size: selection.kv_cache_block_size,
655	        tower_connector_lora_enabled: selection.tower_connector_lora_enabled,
